BEGIN;
CREATE TABLE public.xr_room_growth_settings(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),enabled boolean NOT NULL DEFAULT false,auto_break_requested boolean NOT NULL DEFAULT false);
INSERT INTO public.xr_room_growth_settings(singleton)VALUES(true);
ALTER TABLE public.xr_room_growth_settings ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.xr_room_growth_settings FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS xr_room_messages_squad_time ON public.squad_room_messages(squad_id,created_at DESC,id DESC);
CREATE OR REPLACE FUNCTION public.xr_room_growth_admin(p_patch jsonb DEFAULT '{}'::jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public AS $fn$
DECLARE cfg public.xr_room_growth_settings;BEGIN IF auth.uid()IS NULL OR NOT public.is_admin()THEN RAISE EXCEPTION 'Admin only.'USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_patch)IS DISTINCT FROM 'object'OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_patch)k WHERE k NOT IN('enabled','auto_break_requested'))THEN RETURN jsonb_build_object('ok',false,'error','Invalid room setting.');END IF;
 SELECT * INTO cfg FROM public.xr_room_growth_settings WHERE singleton FOR UPDATE;SELECT * INTO cfg FROM jsonb_populate_record(cfg,p_patch);UPDATE public.xr_room_growth_settings SET enabled=cfg.enabled,auto_break_requested=cfg.auto_break_requested WHERE singleton;
 RETURN jsonb_build_object('ok',true,'growth_enabled',cfg.enabled,'auto_break_requested',cfg.auto_break_requested,'auto_break_enabled',false);EXCEPTION WHEN not_null_violation OR invalid_text_representation THEN RETURN jsonb_build_object('ok',false,'error','Invalid room setting.');END $fn$;
REVOKE ALL ON FUNCTION public.xr_room_growth_admin(jsonb)FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.xr_room_growth_admin(jsonb)TO authenticated;
CREATE OR REPLACE FUNCTION public.xr_room_growth()RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public AS $fn$
DECLARE u uuid:=public.xr_sf_actor();sid uuid;sq public.squads;cfg public.xr_room_growth_settings;x public.xr_sf_squad_settings;roster jsonb;activity jsonb;weekly jsonb;plan jsonb;nextmatch jsonb;rivalry jsonb;n integer;pending bigint;day_key date:=(statement_timestamp()AT TIME ZONE 'Asia/Kolkata')::date;day_start timestamptz;week_start timestamptz;lastmsg timestamptz;mine timestamptz;streak integer;
BEGIN
 SELECT squad_id INTO sid FROM public.squad_members WHERE user_id=u;IF sid IS NULL THEN RETURN jsonb_build_object('ok',false,'error','no_squad');END IF;
 SELECT * INTO sq FROM public.squads WHERE id=sid;IF sq.id IS NULL OR public.is_blocked(u,sq.captain)THEN RETURN jsonb_build_object('ok',false,'error','Squad unavailable.');END IF;
 SELECT * INTO cfg FROM public.xr_room_growth_settings WHERE singleton;SELECT * INTO x FROM public.xr_sf_squad_settings WHERE squad_id=sid;SELECT count(*)INTO n FROM public.squad_members WHERE squad_id=sid;
 SELECT coalesce(jsonb_agg(z.member ORDER BY z.joined_at,z.id),'[]'::jsonb)INTO roster FROM(
 SELECT pr.id,m.joined_at,jsonb_build_object('id',pr.id,'name',coalesce(nullif(pr.ign,''),pr.username,'Player'),'avatar_url',pr.avatar_url,'membership_role',m.role,'combat_role',mp.combat_role,'is_captain',sq.captain=pr.id,'is_me',pr.id=u)member
 FROM public.squad_members m JOIN public.profiles pr ON pr.id=m.user_id LEFT JOIN public.xr_sf_member_prefs mp ON mp.squad_id=m.squad_id AND mp.user_id=m.user_id
 WHERE m.squad_id=sid AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id)ORDER BY m.joined_at,pr.id LIMIT 20)z;
 IF cfg.enabled THEN
 IF sq.captain=u THEN SELECT count(*)INTO pending FROM public.xr_sf_join_requests j JOIN public.profiles pr ON pr.id=j.user_id WHERE j.squad_id=sid AND j.status='pending'AND j.expires_at>statement_timestamp()AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id);END IF;
 SELECT jsonb_build_object('body',body,'revision',revision,'updated_at',updated_at,'source','captain_strategy_plan')INTO plan FROM public.xr_sf_strategy_plans WHERE squad_id=sid;
 day_start:=day_key::timestamp AT TIME ZONE 'Asia/Kolkata';week_start:=date_trunc('week',statement_timestamp()AT TIME ZONE 'Asia/Kolkata')AT TIME ZONE 'Asia/Kolkata';
 SELECT max(m.created_at),max(m.created_at)FILTER(WHERE m.user_id=u)INTO lastmsg,mine FROM public.squad_room_messages m JOIN public.profiles pr ON pr.id=m.user_id WHERE m.squad_id=sid AND m.created_at<=statement_timestamp()AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id);
 WITH days AS(SELECT DISTINCT(m.created_at AT TIME ZONE 'Asia/Kolkata')::date msg_day FROM public.squad_room_messages m JOIN public.profiles pr ON pr.id=m.user_id WHERE m.squad_id=sid AND m.created_at>=day_start-interval '90 days'AND m.created_at<=statement_timestamp()AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id)),recent AS(SELECT msg_day,row_number()OVER(ORDER BY msg_day DESC)n FROM days),anchor AS(SELECT max(msg_day)msg_day FROM days)
 SELECT count(*)FILTER(WHERE r.msg_day=a.msg_day-(r.n::integer-1))::integer INTO streak FROM recent r CROSS JOIN anchor a WHERE a.msg_day>=day_key-1;
 SELECT coalesce(jsonb_agg(z.item ORDER BY z.messages DESC,z.id),'[]'::jsonb)INTO weekly FROM(
 SELECT pr.id,count(*)messages,jsonb_build_object('id',pr.id,'handle',coalesce(nullif(pr.ign,''),pr.username,'Player'),'messages',count(*))item FROM public.squad_room_messages m JOIN public.profiles pr ON pr.id=m.user_id JOIN public.squad_members sm ON sm.squad_id=sid AND sm.user_id=pr.id WHERE m.squad_id=sid AND m.created_at>=week_start AND m.created_at<=statement_timestamp()AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id)AND(pr.id=u OR coalesce(pr.show_activity,false))GROUP BY pr.id,pr.ign,pr.username ORDER BY count(*)DESC,pr.id LIMIT 20)z;
 activity:=jsonb_build_object('messages_today',(SELECT count(*)FROM public.squad_room_messages m JOIN public.profiles pr ON pr.id=m.user_id WHERE m.squad_id=sid AND m.created_at>=day_start AND m.created_at<day_start+interval '1 day'AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id)),
 'weekly_counts',weekly,'last_message_at',lastmsg,'days_since_last_message',CASE WHEN lastmsg IS NOT NULL THEN day_key-(lastmsg AT TIME ZONE 'Asia/Kolkata')::date END,'my_last_message_at',mine,'days_since_my_last_message',CASE WHEN mine IS NOT NULL THEN day_key-(mine AT TIME ZONE 'Asia/Kolkata')::date END,'streak_days',coalesce(streak,0),'streak_basis','visible_room_message_days_IST','streak_lookback_days',90,'reward_coins',NULL);
 SELECT jsonb_build_object('match_id',m.id,'title',m.title,'tournament_id',m.tournament_id,'starts_at',m.starts_at,'registration_owner',jsonb_build_object('id',pr.id,'name',coalesce(nullif(pr.ign,''),pr.username,'Player')),'registered_squad_name',r.squad,'checkin_scope','registration_owner_only','registration_owner_checked_in',EXISTS(SELECT 1 FROM public.match_checkins c WHERE c.match_id=m.id AND c.user_id=r.user_id),'per_member_checkins',NULL,'access_enabled',coalesce(a.enabled,false),'checkin_opens_at',CASE WHEN a.enabled THEN coalesce(a.checkin_opens_at,m.starts_at-interval '60 minutes')END,'checkin_closes_at',CASE WHEN a.enabled THEN coalesce(a.checkin_closes_at,m.starts_at+interval '15 minutes')END)
 INTO nextmatch FROM public.registrations r JOIN public.squad_members sm ON sm.squad_id=sid AND sm.user_id=r.user_id JOIN public.profiles pr ON pr.id=r.user_id JOIN public.matches m ON m.tournament_id=r.tournament_id LEFT JOIN public.xr_match_access_settings a ON a.match_id=m.id
 WHERE m.starts_at>=statement_timestamp()AND m.status NOT IN('done','cancelled')AND r.status NOT IN('rejected','cancelled','declined','waitlist')AND NOT coalesce(r.hold,false)AND NOT coalesce(pr.banned,false)AND NOT public.is_blocked(u,pr.id)ORDER BY m.starts_at,m.id,r.id LIMIT 1;
 SELECT jsonb_build_object('id',w.id,'opponent',other.name,'scheduled_at',w.scheduled_at,'status',w.status,'ready_states',NULL,'source','squad_wars_squad_ids')INTO rivalry FROM public.squad_wars w JOIN public.squads other ON other.id=CASE WHEN w.challenger_id=sid THEN w.opponent_id ELSE w.challenger_id END JOIN public.profiles captain ON captain.id=other.captain WHERE(sid=w.challenger_id OR sid=w.opponent_id)AND w.status='scheduled'AND w.scheduled_at>=statement_timestamp()AND NOT coalesce(captain.banned,false)AND NOT public.is_blocked(u,captain.id)ORDER BY w.scheduled_at,w.id LIMIT 1;
 END IF;
 RETURN jsonb_build_object('ok',true,'growth_enabled',cfg.enabled,'squad',jsonb_build_object('id',sid,'name',sq.name,'tag',sq.tag,'city',NULL,'tier',NULL,'city_rank',NULL,'region',CASE WHEN cfg.enabled THEN x.region END,'member_count',n,'max_members',coalesce(x.max_members,6),'open_seats',greatest(coalesce(x.max_members,6)-n,0),'is_captain',sq.captain=u,'members',roster),
 'pending_join_requests',pending,'next_match',nextmatch,'pin',plan,'poll',NULL,'activity',activity,'voice_presence',NULL,'rivalry',rivalry,'auto_break_requested',cfg.auto_break_requested,'auto_break_enabled',false,'auto_break_deadline',NULL,'friends_without_clan',NULL,'member_last_seen',NULL,'birthday',NULL,'secret_expiring_strategy',NULL,'clan_fund',NULL,'igl_shoutout',NULL,'coin_rewards_available',false,'notification_delivery_available',false,'cache_seconds',30,'count_refresh_seconds',300);
END $fn$;
REVOKE ALL ON FUNCTION public.xr_room_growth()FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.xr_room_growth()TO authenticated;
NOTIFY pgrst,'reload schema';COMMIT;
